mk = np.load(WORK / 'eli5_mkid.npy'); mn = np.load(WORK / 'eli5_mnorm.npy')
c = np.load(WORK / 'eli5_clocal.npy'); t = np.load(WORK / 'eli5_t.npy')
Ws = {l: W(l).float().cpu().numpy() for l in range(16, L)}
def shift(factors):     # factors: {layer: array over neurons, 1 = unchanged}; direct first-order write of the edit
    tot = np.zeros(rd.shape[1], dtype=np.float32)
    for l, f in factors.items():
        tot += Ws[l] @ ((f - 1.0) * mn[l])
    return tot
def report(name, factors):
    s = shift(factors)
    out = []
    for ref in (20, 24, 28, L - 1):
        u = rd[ref] / np.linalg.norm(rd[ref])
        out.append(f'L{ref}: {float(s @ u) / np.linalg.norm(rd[ref]):+.2f}')
    print(f'{name:>28}: |shift| {np.linalg.norm(s):6.1f}; along kid diff (fraction of the gap) ' + '  '.join(out))
ops = json.loads((WORK / 'ops_eli5_1024.json').read_text())
f1024 = {l: np.ones(mn.shape[1], np.float32) for l in range(16, L)}
for o in ops:
    f1024[o['layer']][o['neurons']] = o['factor']
report('eli5-n1024 (tested)', f1024)
# Upper bound for scaling: every neuron in L16-31 set exactly to its kid mean (ratio, any sign)
full = {l: np.where(np.abs(mn[l]) > 1e-3, mk[l] / np.where(np.abs(mn[l]) > 1e-3, mn[l], 1), 1).astype(np.float32) for l in range(16, L)}
report('all L16-31, exact ratio', full)
for lo in (16, 24):
    for fmax in (3, 10):
        for neg in (False, True):
            ff = {}
            for l in range(16, L):
                r = full[l] if l >= lo else np.ones_like(full[l])
                ff[l] = np.clip(r, -fmax if neg else 0, fmax)
            report(f'all L{lo}+ clip{"±" if neg else "0.."}{fmax}', ff)
print('|gap| per layer', {l: round(float(np.linalg.norm(rd[l])), 1) for l in (16, 20, 24, 28, 31)})

