import numpy as np, json
gi = np.load(WORK / 'eli5i_gi.npy'); m0 = np.load(WORK / 'eli5i_m0.npy'); sign_ok = np.load(WORK / 'eli5_signok.npy')
Ws = {l: W(l).float().cpu().numpy() for l in range(L)}
U = {l: gi[l] / np.linalg.norm(gi[l]) for l in range(L)}
along = np.zeros_like(m0); cosv = np.zeros_like(m0)
for l in range(16, L):
    A = Ws[l] * m0[l][None]                      # plain-level write of each neuron
    along[l] = U[l] @ A; cosv[l] = along[l] / (np.linalg.norm(A, axis=0) + 1e-9)
np.save(WORK / 'eli5_along.npy', along); np.save(WORK / 'eli5_cos.npy', cosv)
def evaluate(sel, f):
    out = []
    for ref in (24, 28, 31):
        s = np.zeros(gi.shape[1], np.float32)
        for l, ns in sel.items():
            if l <= ref and len(ns):
                s += (f - 1) * (Ws[l][:, ns] @ m0[l, ns])
        a = float(s @ U[ref]); p = np.linalg.norm(s - a * U[ref])
        out.append((a / np.linalg.norm(gi[ref]), p / np.linalg.norm(gi[ref])))
    return out
def pick(score, k, lo=16, hi=31, minc=0.0):
    sel = {}
    for l in range(lo, hi + 1):
        s = np.where((sign_ok[l] >= 0.9) & (along[l] > 0) & (cosv[l] >= minc), score[l], -np.inf)
        sel[l] = [int(n) for n in np.argsort(-s)[:k] if np.isfinite(s[n])]
    return sel
rows = []
for name, score in (('proj', along), ('cos', cosv)):
    for hi in (31, 29):
        for k in (64, 128, 256, 512):
            sel = pick(score, k, hi=hi)
            for f in (2, 3, 4, 6):
                r = evaluate(sel, f)
                rows.append((name, hi, k, f, sum(len(v) for v in sel.values()), r))
for name, hi, k, f, n, r in rows:
